def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: The timedelta instance to dehydrate.
    :type value: datetime.timedelta
    :return: The total number of seconds represented by the timedelta, or None if value is None.
    """
    if value is None:
        return None
    return value.total_seconds()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        x = value.x
        y = value.y
    except AttributeError:
        raise TypeError("Expected a Point-like object with x and y attributes")
    coords = [x, y]
    if hasattr(value, 'z'):
        coords.append(value.z)
    return tuple(coords)

def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Ensure the class has a mapping of protocol handlers.
        # It is expected to be defined as a class attribute named
        # `_protocol_handlers` mapping tuples to handler classes.
        if not hasattr(cls, "_protocol_handlers"):
            raise AttributeError(
                f"{cls.__name__} does not define a `_protocol_handlers` mapping"
            )

        handlers = cls._protocol_handlers

        if protocol_version is None:
            # Return a shallow copy to prevent accidental mutation.
            return dict(handlers)

        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )

        # Return a dict containing the handler if the version is supported.
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Try to get the underlying mapping that stores the data.
    # Prefer an explicit attribute if present; otherwise fall back
    # to treating the instance as a mapping.
    mapping = getattr(self, "_data", None)
    if mapping is None:
        try:
            mapping = dict(self)
        except Exception:
            mapping = {}

    # If no keys are supplied, return all values in order.
    if not keys:
        return list(mapping.values())

    # Otherwise, filter by the supplied keys or indices.
    result = []
    for key in keys:
        if isinstance(key, int):
            # Treat as an index into the ordered keys.
            try:
                k = list(mapping.keys())[key]
                result.append(mapping[k])
            except IndexError:
                # Skip if the index is out of range.
                continue
        else:
            # Treat as a key lookup.
            if key in mapping:
                result.append(mapping[key])
    return result

def data(self, *keys):
        """ Return the keys and values of this record as a dictionary,
        optionally including only certain values by index or key. Keys
        provided in the items that are not in the record will be
        inserted with a value of :const:`None`; indexes provided
        that are out of bounds will trigger an :exc:`IndexError`.

        :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
        :return: dictionary of values, keyed by field name
        :raises: :exc:`IndexError` if an out-of-bounds index is specified
        """
        # If no specific keys are requested, return all items
        if not keys:
            return dict(zip(self._keys, self._values))

        result = {}
        for k in keys:
            if isinstance(k, int):
                # Index-based access
                if k < 0 or k >= len(self._values):
                    raise IndexError(f"Index {k} out of bounds")
                key_name = self._keys[k]
                result[key_name] = self._values[k]
            else:
                # Key-based access
                if k in self._keys:
                    idx = self._keys.index(k)
                    result[k] = self._values[idx]
                else:
                    result[k] = None
        return result

