def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        order = []  # list of keys in LRU order (oldest first)

        def make_key(args, kwargs):
            if typed:
                key = tuple((arg, type(arg)) for arg in args)
                kw = tuple((k, v, type(v)) for k, v in sorted(kwargs.items()))
            else:
                key = args
                kw = tuple(sorted(kwargs.items()))
            return key, kw

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            # Check cache
            if key in cache:
                value, expire = cache[key]
                if expire > now:
                    # Move key to end to mark as recently used
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
                    order.append(key)
                    return value
                else:
                    # expired
                    del cache[key]
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
            # Compute new value
            result = func(*args, **kwargs)
            expire_time = now + ttl
            cache[key] = (result, expire_time)
            order.append(key)
            # Evict if over maxsize
            if len(order) > maxsize:
                oldest = order.pop(0)
                cache.pop(oldest, None)
            return result

        return wrapper
    return decorator

