def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        # If the item is a sequence (list or tuple), recursively expand it
        if isinstance(item, (list, tuple)):
            _normalizeargs(item, output)
        # If the item looks like a Declaration with an 'interfaces' attribute,
        # expand it into its interfaces
        elif hasattr(item, "interfaces"):
            output.extend(item.interfaces)
        # If the item is an implements spec (could be any object), keep it as is
        else:
            output.append(item)
    return output

