def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    # Regular expressions for label keys and values.
    # These are simplified versions of Kubernetes label regexes.
    key_regex = re.compile(r'^$|^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')
    value_regex = re.compile(r'^$|^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')

    errors = []

    for k, v in labels.items():
        # Validate key type
        if not isinstance(k, (str, bytes)):
            errors.append({str(k): 'expected string or bytes-like object'})
            continue

        # Validate key regex
        if not key_regex.match(k):
            errors.append({k: f"Label key '{k}' does not match the regex [...]"})

        # Validate value
        if isinstance(v, (list, tuple)):
            for idx, item in enumerate(v):
                if not isinstance(item, (str, bytes)):
                    errors.append({str(item): 'expected string or bytes-like object'})
                else:
                    if not value_regex.match(item):
                        errors.append({item: f"Label value '{item}' does not match the regex [...]"})
        else:
            if not isinstance(v, (str, bytes)):
                errors.append({str(v): 'expected string or bytes-like object'})
            else:
                if not value_regex.match(v):
                    errors.append({v: f"Label value '{v}' does not match the regex [...]"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to a default observer schema.
    """
    # Retrieve the existing custom observer schemas, if any
    custom_schemas = getattr(app.spec, "observer_schema", {})
    if custom_schemas is None:
        custom_schemas = {}

    default_schema = {}
    # Iterate over all resources defined in the application's manifest
    for resource in getattr(app.spec, "manifest", []):
        kind = getattr(resource, "kind", None)
        if not kind:
            continue  # Skip resources without a kind

        # Skip kinds that already have a custom observer schema
        if kind in custom_schemas:
            continue

        # Build a very generic default schema that captures the most common fields
        # of a Kubernetes resource: metadata, spec, and status.
        default_schema[kind] = {
            "metadata": {
                "name": {"type": "string"},
                "namespace": {"type": "string"},
            },
            "spec": {"type": "object"},
            "status": {"type": "object"},
        }

    return default_schema

