def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")

    # Determine spec version
    spec_version = self.spec_version
    if extract_spec_version:
        type_value = inventory.get("type")
        type_to_version = {
            "inventory": "1.0",
            "inventory_v2": "2.0",
            "inventory_v3": "3.0",
        }
        if type_value in type_to_version:
            spec_version = type_to_version[type_value]

    # Validation logic per spec version
    if spec_version == "1.0":
        required_keys = ["name", "items"]
        for key in required_keys:
            if key not in inventory:
                raise ValueError(f"Missing required key '{key}' for spec version 1.0.")
        if not isinstance(inventory["items"], list):
            raise ValueError("The 'items' key must be a list.")
        for item in inventory["items"]:
            if not isinstance(item, dict):
                raise ValueError("Each item must be a dictionary.")
            if "id" not in item or "quantity" not in item:
                raise ValueError("Each item must contain 'id' and 'quantity'.")

    elif spec_version == "2.0":
        required_keys = ["name", "items", "metadata"]
        for key in required_keys:
            if key not in inventory:
                raise ValueError(f"Missing required key '{key}' for spec version 2.0.")
        if not isinstance(inventory["items"], list):
            raise ValueError("The 'items' key must be a list.")
        for item in inventory["items"]:
            if not isinstance(item, dict):
                raise ValueError("Each item must be a dictionary.")
            if "id" not in item or "quantity" not in item:
                raise ValueError("Each item must contain 'id' and 'quantity'.")
        if not isinstance(inventory["metadata"], dict):
            raise ValueError("The 'metadata' key must be a dictionary.")

    else:
        raise ValueError(f"Unsupported spec version: {spec_version}")

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type as self
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same class as self")

    # Both objects must expose a 'version' attribute
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        raise AttributeError("Both inventories must have a 'version' attribute")

    # Prior version must be strictly less than the current version
    if prior.version >= self.version:
        raise ValueError(
            f"Prior version {prior.version} must be less than current version {self.version}"
        )

    # Both objects must expose an 'inventory' attribute
    if not hasattr(self, "inventory") or not hasattr(prior, "inventory"):
        raise AttributeError("Both inventories must have an 'inventory' attribute")

    # Helper to compare inventories
    def _check_subset(curr_inv, prior_inv):
        # If inventories are dictionaries mapping items to quantities
        if isinstance(curr_inv, dict) and isinstance(prior_inv, dict):
            for item, qty in prior_inv.items():
                if item not in curr_inv:
                    raise ValueError(
                        f"Item '{item}' present in prior inventory but missing in current inventory"
                    )
                if curr_inv[item] < qty:
                    raise ValueError(
                        f"Quantity of item '{item}' in current inventory ({curr_inv[item]}) "
                        f"is less than in prior ({qty})"
                    )
        else:
            # Treat inventories as iterables (e.g., lists or sets)
            curr_set = set(curr_inv)
            prior_set = set(prior_inv)
            missing = prior_set - curr_set
            if missing:
                raise ValueError(
                    f"Items {missing} present in prior inventory but missing in current inventory"
                )

    # Perform the subset check
    _check_subset(self.inventory, prior.inventory)

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Build a mapping from version to state
    if isinstance(inventory, dict):
        if 'versions' in inventory:
            versions_map = inventory['versions']
        else:
            # Assume inventory itself is a mapping of version -> state
            versions_map = inventory
    else:
        # Assume inventory is a list of dicts with 'version' and 'state' keys
        versions_map = {v['version']: v['state'] for v in inventory}

    # Normalize state objects: if a state dict contains a 'state' key, use it
    def _get_state(state_obj):
        if isinstance(state_obj, dict) and 'state' in state_obj:
            return state_obj['state']
        return state_obj

    # Sort versions (assuming they are comparable; fallback to string)
    sorted_versions = sorted(versions_map.keys(), key=lambda v: str(v))

    # Find the target version index
    try:
        target_index = sorted_versions.index(version)
    except ValueError:
        # Version not found; return empty mapping
        return {}

    # Get the target state's logical path mapping
    target_state = _get_state(versions_map[version])

    result = {}
    for logical_path, content in target_state.items():
        # Normalize content to a set of files
        if isinstance(content, (list, set, tuple)):
            files_set = set(content)
        else:
            files_set = {content}

        # Include duplicates from later versions
        for later_version in sorted_versions[target_index + 1 :]:
            later_state = _get_state(versions_map[later_version])
            if logical_path in later_state:
                later_content = later_state[logical_path]
                if isinstance(later_content, (list, set, tuple)):
                    files_set.update(later_content)
                else:
                    files_set.add(later_content)

        result[logical_path] = files_set

    return result

