def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
            if result:
                value = result[0]
                if isinstance(value, str):
                    return value.strip()
                # If it's an element, try to get its text content
                if hasattr(value, 'text'):
                    return value.text.strip() if value.text else None
                if hasattr(value, 'text_content'):
                    return value.text_content().strip()
                return value
        except Exception:
            # ignore malformed xpath or evaluation errors
            continue
    return None

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        def _pretty(obj, level):
            pad = ' ' * level
            if isinstance(obj, (list, tuple)):
                lines = [f"{pad}{type(obj).__name__}:"]
                for i, item in enumerate(obj):
                    lines.append(f"{pad}  [{i}]:")
                    lines.append(_pretty(item, level + 4))
                return '\n'.join(lines)
            if isinstance(obj, dict):
                lines = [f"{pad}dict:"]
                for k, v in sorted(obj.items(), key=lambda x: str(x[0])):
                    lines.append(f"{pad}  {k!r}:")
                    lines.append(_pretty(v, level + 4))
                return '\n'.join(lines)
            if hasattr(obj, "__dict__") and not isinstance(obj, type):
                lines = [f"{pad}{obj.__class__.__name__}:"]
                for k in sorted(obj.__dict__):
                    v = getattr(obj, k)
                    lines.append(f"{pad}  {k}:")
                    lines.append(_pretty(v, level + 4))
                return '\n'.join(lines)
            # Fallback to repr
            return f"{pad}{repr(obj)}"

        result = _pretty(self, indent)
        if debug:
            result += f"\n{' ' * indent}# Debug: type={type(self).__name__}"
        return result

def tzname_in_python2(namefunc):
    import sys
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3:
            if isinstance(result, unicode):
                return result.encode('utf-8')
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to get the package version using importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import version, PackageNotFoundError
        # Determine the top-level package name
        pkg_name = __package__ or __name__
        top_pkg = pkg_name.split('.')[0]
        return version(top_pkg)
    except Exception:
        # Fallback: try to read a VERSION file in the current directory
        try:
            with open('VERSION', 'r', encoding='utf-8') as f:
                return f.read().strip()
        except Exception:
            # Default version if all methods fail
            return '0.0.0'

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Convert all pieces to strings
    parts = [str(p) for p in pieces]
    style = style.lower()

    # Helper to find the first non-numeric part
    def first_non_numeric_index(parts):
        for i, p in enumerate(parts):
            if not p.isdigit():
                return i
        return len(parts)

    if style == "short":
        # Only numeric components, joined by dots
        numeric = [p for p in parts if p.isdigit()]
        return ".".join(numeric)

    if style == "full":
        # Join everything with dots
        return ".".join(parts)

    if style == "semver":
        idx = first_non_numeric_index(parts)
        core = ".".join(parts[:idx])
        if idx < len(parts):
            pre = parts[idx]
            pre_parts = parts[idx + 1 :]
            pre_str = pre
            if pre_parts:
                pre_str += "." + ".".join(pre_parts)
            return f"{core}-{pre_str}"
        return core

    if style == "pep440":
        idx = first_non_numeric_index(parts)
        core = ".".join(parts[:idx])
        if idx < len(parts):
            pre = parts[idx]
            pre_parts = parts[idx + 1 :]
            # Map common pre-release identifiers to PEP 440 tokens
            mapping = {
                "alpha": "a",
                "beta": "b",
                "rc": "rc",
                "pre": "rc",
                "preview": "rc",
                "dev": "dev",
                "post": "post",
            }
            pre_prefix = mapping.get(pre.lower(), pre.lower())
            pre_str = pre_prefix
            if pre_parts:
                # PEP 440 concatenates numeric parts without separators
                pre_str += "".join(pre_parts)
            return f"{core}{pre_str}"
        return core

    # Default: join with dots
    return ".".join(parts)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    for p in pieces:
        if p == '+':
            return '.'
    return '+'

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Ensure a registry exists on the function object
    if not hasattr(register_vcs_handler, "registry"):
        register_vcs_handler.registry = {}
    # If the second argument is a callable, register it immediately
    if callable(method):
        register_vcs_handler.registry[vcs] = method
        return method
    # Otherwise, treat the call as a decorator factory
    def decorator(func):
        register_vcs_handler.registry[vcs] = func
        return func
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
