        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    valid = obj.validate()
                else:
                    valid = True
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Validation error for {obj}: {e}")

        if check_digests and valid:
            try:
                if hasattr(obj, "digest") and hasattr(obj, "compute_digest"):
                    if obj.digest != obj.compute_digest():
                        valid = False
                        if show_warnings:
                            print(f"Digest mismatch for {obj}")
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Digest check error for {obj}: {e}")

        if valid:
            good_objects += 1

        # Recurse into children if present
        if hasattr(obj, "children"):
            for child in obj.children:
                _validate(child)

    for root_obj in iterable:
        _validate(root_obj)

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have the root inventory loaded
    if not hasattr(self, 'root_inventory') or self.root_inventory is None:
        root_inv_path = os.path.join(self.root_dir, 'inventory.json')
        if not os.path.isfile(root_inv_path):
            raise FileNotFoundError(f"Root inventory file not found at {root_inv_path}")
        with open(root_inv_path, 'r', encoding='utf-8') as f:
            try:
                self.root_inventory = json.load(f)
            except Exception as e:
                raise ValueError(f"Failed to parse root inventory: {e}")

    differences = {}
    for vdir in version_dirs:
        inv_path = os.path.join(self.root_dir, vdir, 'inventory.json')
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing in version directory '{vdir}'.")
        with open(inv_path, 'r', encoding='utf-8') as f:
            try:
                inv = json.load(f)
            except Exception as e:
                raise ValueError(f"Failed to parse inventory in '{vdir}': {e}")

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory in '{vdir}' is not a mapping.")

        diff = {}
        for path, digest in inv.items():
            root_digest = self.root_inventory.get(path)
            if root_digest is None:
                # File not present in root inventory; skip or record as needed
                continue
            if digest != root_digest:
                diff[path] = (root_digest, digest)

        if diff:
            differences[vdir] = diff

    return differences

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if bug_ids is None:
        return params
    if isinstance(bug_ids, str):
        params['ids'] = bug_ids
    else:
        try:
            iterable = list(bug_ids)
        except TypeError:
            params['ids'] = str(bug_ids)
        else:
            if not iterable:
                params['ids'] = ''
            else:
                ids = []
                for item in iterable:
                    if hasattr(item, 'id'):
                        ids.append(str(item.id))
                    else:
                        ids.append(str(item))
                params['ids'] = ','.join(ids)
    return params

def deep_merge_nodes(nodes):
    '''
    Merge a list of (ScalarNode, value) tuples, deep‑merging MappingNode values for duplicate keys.
    '''
    def merge_mapping_nodes(node1, node2):
        # Merge two MappingNode objects recursively.
        merged_pairs = []
        key_map = {}

        # Process first mapping
        for k_node, v_node in node1.value:
            key = k_node.value
            key_map[key] = (k_node, v_node)

        # Process second mapping, merging where necessary
        for k_node, v_node in node2.value:
            key = k_node.value
            if key in key_map:
                existing_k, existing_v = key_map[key]
                if isinstance(existing_v, ruamel.yaml.nodes.MappingNode) and isinstance(v_node, ruamel.yaml.nodes.MappingNode):
                    merged_v = merge_mapping_nodes(existing_v, v_node)
                    key_map[key] = (existing_k, merged_v)
                else:
                    key_map[key] = (existing_k, v_node)
            else:
                key_map[key] = (k_node, v_node)

        # Build merged list preserving order: first mapping order, then new keys from second
        seen = set()
        for k_node, v_node in node1.value:
            key = k_node.value
            if key not in seen:
                seen.add(key)
                merged_pairs.append(key_map[key])
        for k_node, v_node in node2.value:
            key = k_node.value
            if key not in seen:
                seen.add(key)
                merged_pairs.append(key_map[key])

        return ruamel.yaml.nodes.MappingNode(tag=node1.tag, value=merged_pairs)

    # Main merge logic
    result = []
    key_map = {}

    for key_node, val_node in nodes:
        key = key_node.value
        if key in key_map:
            existing_val = key_map[key]
            if isinstance(existing_val, ruamel.yaml.nodes.MappingNode) and isinstance(val_node, ruamel.yaml.nodes.MappingNode):
                merged_val = merge_mapping_nodes(existing_val, val_node)
                key_map[key] = merged_val
            else:
                key_map[key] = val_node
        else:
            key_map[key] = val_node

    # Preserve order of first appearance of each key
    seen = set()
    for key_node, _ in nodes:
        key = key_node.value
        if key not in seen:
            seen.add(key)
            result.append((key_node, key_map[key]))

    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_mapping_nodes(node1, node2):
        # Both are MappingNode
        # Build dicts of key_value -> (key_node, value_node)
        def to_dict(node):
            d = {}
            order = []
            for k, v in node.value:
                key_val = k.value
                d[key_val] = (k, v)
                order.append(key_val)
            return d, order

        d1, order1 = to_dict(node1)
        d2, order2 = to_dict(node2)

        # Merge d2 into d1
        for key_val in order2:
            k2, v2 = d2[key_val]
            if key_val in d1:
                k1, v1 = d1[key_val]
                # If both values are MappingNode, merge recursively
                if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
                    merged_val = merge_mapping_nodes(v1, v2)
                else:
                    # Last wins
                    merged_val = v2
                d1[key_val] = (k1, merged_val)
            else:
                d1[key_val] = (k2, v2)
                order1.append(key_val)

        # Reconstruct list of tuples preserving order
        merged_list = [(d1[k][0], d1[k][1]) for k in order1]
        return MappingNode(tag=node1.tag, value=merged_list)

    merged_dict = {}
    order = []

    for key_node, val_node in nodes:
        key_val = key_node.value
        if key_val in merged_dict:
            existing_val = merged_dict[key_val][1]
            if isinstance(existing_val, MappingNode) and isinstance(val_node, MappingNode):
                merged_val = merge_mapping_nodes(existing_val, val_node)
            else:
                merged_val = val_node
            merged_dict[key_val] = (key_node, merged_val)
        else:
            merged_dict[key_val] = (key_node, val_node)
            order.append(key_val)

    result = [(merged_dict[k][0], merged_dict[k][1]) for k in order]
    return result

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("size must be a string")
    s = size.strip()
    if not s:
        raise ValueError("size string is empty")

    # Define unit multipliers (decimal units)
    units = {
        'B': 1,
        'K': 10**3,
        'M': 10**6,
        'G': 10**9,
        'T': 10**12,
        'P': 10**15,
        'E': 10**18,
    }

    # If the last character is a letter, treat it as a unit
    if s[-1].isalpha():
        unit = s[-1].upper()
        if unit not in units:
            raise ValueError(f"Unknown unit '{unit}' in size '{size}'")
        try:
            number = float(s[:-1].strip())
        except ValueError as exc:
            raise ValueError(f"Invalid numeric value in size '{size}'") from exc
        multiplier = units[unit]
        return int(round(number * multiplier))
    else:
        # No unit, interpret as plain number of bytes
        try:
            return int(s)
        except ValueError as exc:
            raise ValueError(f"Invalid size string '{size}'") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Treat actual None as a None representation
    if val is None:
        return True
    # Only strings can represent a None value
    if not isinstance(val, str):
        return False
    # Normalize the string: strip whitespace and convert to lowercase
    normalized = val.strip().lower()
    # Common representations of None
    none_representations = {"none", "null", "nil", "na", "n/a", ""}
    return normalized in none_representations

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        flags.extend(action.option_strings)
    return ' '.join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two symbols")
    sign = ''
    if number < 0:
        sign = '-'
        number = -number
    digits = []
    if number == 0:
        digits.append(alphabet[0])
    else:
        while number > 0:
            digits.append(alphabet[number % base])
            number //= base
    digits.reverse()
    result = ''.join(digits)
    if padding is not None:
        pad_len = padding - len(result)
        if pad_len > 0:
            result = alphabet[0] * pad_len + result
    return sign + result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if register_value is None:
        return flow_params
    for flow in flow_params.values():
        if isinstance(flow, dict) and register_value in flow:
            flow[register_value] = register_number
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        return value
    return value.replace('.', str(arg))

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subs = set(cls.__subclasses__())
    for sub in list(subs):
        subs.update(subclasses(sub))
    return subs

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must not be empty")
    # Map each character in the alphabet to its numeric value
    char_to_val = {ch: i for i, ch in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in char_to_val:
            raise ValueError(f"Character {ch!r} not in alphabet")
        result = result * base + char_to_val[ch]
    return result

