def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = frequency.strip().lower()
    if freq == "always":
        return None
    if not freq:
        raise ValueError("Empty frequency string")
    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Frequency '{frequency}' must be in the form '<number> <unit>'")
    number_str, unit = parts
    try:
        number = float(number_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{number_str}'")
    if number < 0:
        raise ValueError("Frequency number must be non-negative")
    unit_map = {
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'second': 'seconds',
        'seconds': 'seconds',
    }
    if unit not in unit_map:
        raise ValueError(f"Unrecognized time unit: '{unit}'")
    kwargs = {unit_map[unit]: number}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    # Direct string checks
    if host.lower() == "localhost":
        return True
    if host == "127.0.0.1" or host == "::1":
        return True
    try:
        # Resolve the host to all possible addresses
        for res in socket.getaddrinfo(host, None):
            ip = res[4][0]
            # IPv4 loopback
            if ip == "127.0.0.1":
                return True
            # IPv6 loopback
            if ip == "::1":
                return True
            # IPv4-mapped IPv6 loopback
            if ip.startswith("::ffff:127.0.0.1"):
                return True
    except socket.gaierror:
        # Host could not be resolved
        return False
    return False

def is_ipv4(target):
