def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, re, logging

    configs = {}
    errors = []

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_vars(value):
        if isinstance(value, str):
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except Exception as exc:
            # Create a LogRecord for the error
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to load configuration file {filename}: {exc}',
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        # Basic validation: configuration must be a dict
        if not isinstance(data, dict):
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Configuration file {filename} does not contain a JSON object',
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            data.update(overrides)

        # Resolve environment variables if requested
        if resolve_env:
            data = resolve_env_vars(data)

        configs[filename] = data

    return configs, errors

def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    if protocol_version is None:
        # Return a copy to prevent accidental mutation of the class attribute
        return dict(cls._protocol_handlers)
    # Return a single-item dict if the version is supported, otherwise an empty dict
    if protocol_version in cls._protocol_handlers:
        return {protocol_version: cls._protocol_handlers[protocol_version]}
    return {}

def _verify(iface, candidate, tentative=False, vtype=None):
    import inspect
    from zope.interface import Invalid
    errors = []

    # Check interface provision
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"{candidate!r} does not provide interface {iface!r}")

    # Check required methods
    for name in iface.getRequiredMethods():
        if not hasattr(candidate, name):
            errors.append(f"Missing method {name!r} in {candidate!r}")
            continue
        iface_method = getattr(iface, name)
        cand_method = getattr(candidate, name)
        # If candidate is an instance, get the unbound function for signature comparison
        if not inspect.isfunction(cand_method) and hasattr(candidate.__class__, name):
            cand_method = getattr(candidate.__class__, name)
        try:
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(cand_method)
            # Compare parameter lists (names and kinds)
            if iface_sig.parameters != cand_sig.parameters:
                errors.append(
                    f"Signature mismatch for method {name!r}: expected {iface_sig}, got {cand_sig}"
                )
        except (ValueError, TypeError):
            # If signature cannot be inspected, skip comparison
            pass

    # Check required attributes
    for name in iface.getRequiredAttributes():
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute {name!r} in {candidate!r}")

    # Raise collected errors
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Raises a TypeError if the candidate does not satisfy the interface.
    Returns True if the candidate passes the checks.
    """
    # Ensure candidate is a class
    if not isinstance(candidate, type):
        raise TypeError(f"candidate must be a class, got {type(candidate).__name__}")

    # Ensure candidate is a subclass of iface
    try:
        if not issubclass(candidate, iface):
            raise TypeError(f"{candidate.__name__} does not subclass {iface.__name__}")
    except TypeError:
        # issubclass can raise if iface is not a class
        raise TypeError(f"iface must be a class or type, got {type(iface).__name__}")

    # If iface defines abstract methods, check that candidate implements them
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    for name in abstract_methods:
        if tentative:
            continue
        if not hasattr(candidate, name):
            raise TypeError(f"{candidate.__name__} does not implement abstract method {name}")

    # Ensure candidate itself is not abstract (unless tentative)
    candidate_abstract = getattr(candidate, "__abstractmethods__", set())
    if not tentative and candidate_abstract:
        raise TypeError(f"{candidate.__name__} is abstract: {candidate_abstract}")

    return True

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self.key_to_val:
        return None
    freq = self.min_freq
    key_order = self.freq_to_keys[freq]
    key, _ = key_order.popitem(last=False)
    value = self.key_to_val[key]
    del self.key_to_val[key]
    if hasattr(self, 'key_to_freq'):
        del self.key_to_freq[key]
    if not key_order:
        del self.freq_to_keys[freq]
        if self.freq_to_keys:
            self.min_freq = min(self.freq_to_keys.keys())
        else:
            self.min_freq = 0
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self.cache:
        raise KeyError('popitem(): dictionary is empty')
    key, value = self.cache.popitem(last=False)
    return key, value

