def identify_request(request: RequestType):
    """
    Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check for a specific header that might indicate a Diaspora request
    if hasattr(request, "headers"):
        try:
            if request.headers.get("X-Diaspora-Request") == "true":
                return True
        except Exception:
            pass

    # Attempt to extract JSON data from the request
    data = {}
    if hasattr(request, "get_json"):
        try:
            data = request.get_json(silent=True) or {}
        except Exception:
            data = {}
    elif hasattr(request, "json"):
        try:
            data = request.json or {}
        except Exception:
            data = {}
    elif isinstance(request, dict):
        data = request

    # Check for a public message indicator
    if data.get("public") or data.get("type") == "public":
        return True

    # Check for a private message indicator
    if data.get("private") or data.get("type") == "private":
        return True

    # Check for legacy payload indicators
    if data.get("legacy") or data.get("legacy_payload"):
        return True

    return False

