def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        urllib_req = __import__('urllib.request')
        req = urllib_req.Request(url, method='HEAD')
        with urllib_req.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    return {child.tag: child for child in node}

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Normalize base URL and path to avoid duplicate slashes
    base = url.rstrip('/')
    path = document_path or '/nodeinfo'
    # Remove leading/trailing slashes from the path
    path = path.strip('/')
    href_base = f"{base}/{path}"
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": f"{href_base}/2.0"
            },
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.1",
                "href": f"{href_base}/2.1"
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Attempt to use the xmlsec library for verification. If it is not
    # available or any step fails, return False.
    try:
        import xmlsec
        from lxml import etree
    except Exception:
        return False

    try:
        # Parse the XML document
        root = etree.fromstring(doc)
    except Exception:
        return False

    # Find the Signature element (namespace-aware)
    ns = {"ds": "http://www.w3.org/2000/09/xmldsig#"}
    sig_node = root.find(".//ds:Signature", namespaces=ns)
    if sig_node is None:
        return False

    try:
        # Load the public key from PEM format
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    except Exception:
        return False

    try:
        # Create a signature context and verify
        ctx = xmlsec.SignatureContext()
        ctx.key = key
        ctx.verify(sig_node)
        return True
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        subject = data.get('subject')
        aliases = data.get('aliases', [])
        links = data.get('links', [])
        return {'subject': subject, 'aliases': aliases, 'links': links}
    except Exception:
        # Fallback to XRD (XML)
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)

            def _tag(e):
                return e.tag.split('}', 1)[-1] if '}' in e.tag else e.tag

            subject = None
            aliases = []
            links = []

            for child in root:
                t = _tag(child)
                if t == 'Subject':
                    subject = child.text
                elif t == 'Alias':
                    if child.text:
                        aliases.append(child.text)
                elif t == 'Link':
                    href = child.attrib.get('href')
                    if href:
                        links.append({
                            'rel': child.attrib.get('rel'),
                            'type': child.attrib.get('type'),
                            'href': href
                        })
            return {'subject': subject, 'aliases': aliases, 'links': links}
        except Exception:
            # If parsing fails, return empty dict
            return {}

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Ensure the host includes a scheme; default to https
    if not host.startswith(('http://', 'https://')):
        host = 'https://' + host

    # Build the well‑known host‑meta URL
    url = host.rstrip('/') + '/.well-known/host-meta'

    try:
        # Use urllib to fetch the document
        import urllib.request
        with urllib.request.urlopen(url, timeout=10) as response:
            data = response.read()
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve host-meta from {host!r}: {exc}") from exc

    # Parse the XML into an XRD instance
    try:
        return XRD.fromstring(data)
    except Exception as exc:
        raise ValueError(f"Failed to parse host-meta XML from {host!r}: {exc}") from exc

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    import requests
    try:
        # Resolve the HTTP method function from the requests module
        method_func = getattr(requests, method.lower())
    except AttributeError:
        # Unsupported method
        return (None, ValueError(f"Unsupported method: {method}"))

    try:
        # Perform the request with the provided arguments
        response = method_func(url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        # Return the exception instance on failure
        return (None, exc)

