def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Retrieve the collection of commands, supporting common attribute names
    commands = getattr(self, 'commands', None) or getattr(self, '_commands', {})
    command = commands.get(command_name)
    if not command:
        return None
    # Retrieve the options dictionary from the command, supporting common attribute names
    options = getattr(command, 'options', None) or getattr(command, '_options', {})
    return options.get(argument_name)

def get_silent_args(self, args):
    """
    Return a list of argument names that should be considered "silent".
    The method attempts to handle various input types:
    - If `args` is a dict, the keys are inspected.
    - If `args` is a list/tuple, each element is treated as an argument name.
    - If an element is a 2-tuple, the first item is taken as the name.
    An optional attribute `self.silent_args` can be defined as a set or list
    of names that are explicitly marked as silent. In addition, any name
    that starts with '_' or 'no_' is treated as silent by default.
    """
    silent = []
    # Optional explicit silent set defined on the instance
    explicit_silent = getattr(self, "silent_args", set())
    # Ensure we have a set for fast lookup
    if not isinstance(explicit_silent, (set, list, tuple)):
        explicit_silent = set()
    else:
        explicit_silent = set(explicit_silent)

    def is_silent(name):
        return (
            name in explicit_silent
            or (isinstance(name, str) and (name.startswith("_") or name.startswith("no_")))
        )

    if isinstance(args, dict):
        for key in args:
            if is_silent(key):
                silent.append(key)
    elif isinstance(args, (list, tuple)):
        for item in args:
            # If the item is a tuple of (name, value), use the name
            if isinstance(item, tuple) and len(item) == 2:
                name = item[0]
            else:
                name = item
            if is_silent(name):
                silent.append(name)
    return silent

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        for opt in options_spec:
            # Skip if no conditional requirement
            if 'required_when' not in opt:
                continue
            cond = opt['required_when']
            try:
                # If the condition is a string, evaluate it as a Python
                # expression with args as the local namespace.
                if isinstance(cond, str):
                    if eval(cond, {}, args):
                        required.append(opt['name'])
                # If the condition is a callable, call it with args.
                elif callable(cond):
                    if cond(args):
                        required.append(opt['name'])
                # If the condition is a boolean, use it directly.
                elif isinstance(cond, bool):
                    if cond:
                        required.append(opt['name'])
                # For any other type, ignore the condition.
            except Exception:
                # If evaluation fails (e.g., NameError for missing keys),
                # treat the condition as not satisfied.
                continue
        return required

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Expect args to be a mapping of argument names to values.
    # The maximum allowed lengths should be defined in self.max_length
    # as a mapping of argument names to integer limits.
    max_lengths = getattr(self, "max_length", {})
    if not isinstance(max_lengths, dict):
        return

    for key, value in args.items():
        limit = max_lengths.get(key)
        if limit is None:
            continue

        # Handle string and bytes
        if isinstance(value, (str, bytes)):
            if len(value) > limit:
                raise ValueError(
                    f"Argument '{key}' length {len(value)} exceeds maximum allowed {limit}"
                )
        # Handle collections
        elif isinstance(value, (list, tuple, set, dict)):
            if len(value) > limit:
                raise ValueError(
                    f"Argument '{key}' size {len(value)} exceeds maximum allowed {limit}"
                )
        # For other types, skip length validation
        else:
            continue

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # self.choices is expected to be a mapping of argument names to an iterable of allowed values.
    if not hasattr(self, "choices") or not isinstance(self.choices, dict):
        return

    for arg_name, allowed in self.choices.items():
        # Retrieve the value from args, which may be a dict or an object with attributes.
        if isinstance(args, dict):
            if arg_name not in args:
                continue
            value = args[arg_name]
        else:
            if not hasattr(args, arg_name):
                continue
            value = getattr(args, arg_name)

        # Skip if no value was provided.
        if value is None:
            continue

        # If the value is a collection, validate each element.
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {v}. "
                        f"Allowed values: {allowed}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value}. "
                    f"Allowed values: {allowed}"
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :return: True if all argument values are within the defined min and max bounds, False otherwise.
    """
    # If no arguments provided, nothing to validate
    if args is None:
        return True

    # Retrieve min and max bounds from the instance; if not set, skip validation
    min_val = getattr(self, "min", None)
    max_val = getattr(self, "max", None)
    if min_val is None or max_val is None:
        return True

    # Determine iterable of values
    if isinstance(args, dict):
        values = args.values()
    else:
        values = args

    for value in values:
        try:
            if value < min_val or value > max_val:
                return False
        except TypeError:
            # If value cannot be compared, consider it invalid
            return False

    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Normalize spec_option to a dictionary
    if isinstance(spec_option, str):
        spec = {'type': spec_option}
    elif isinstance(spec_option, dict):
        spec = spec_option.copy()
    else:
        spec = {}
    # Construct the complex type representation
    complex_type = {
        'subcommand': subcommand,
        'type_name': type_name,
        'option_name': option_name,
        'spec': spec
    }
    return complex_type

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}

        # Helper to parse a single argument string into key/value
        def _parse_arg(arg):
            # Strip leading dashes
            if arg.startswith("--"):
                key_val = arg[2:].split("=", 1)
            elif arg.startswith("-"):
                key_val = arg[1:].split("=", 1)
            else:
                return None, None
            key = key_val[0]
            if len(key_val) == 2:
                val = key_val[1]
                # Convert common boolean strings to actual bool
                if val.lower() == "true":
                    val = True
                elif val.lower() == "false":
                    val = False
            else:
                val = True
            return key, val

        # Determine which keys are considered control keys.
        # If the instance has a predefined set of control keys, use it.
        # Otherwise, fall back to keys that start with 'control_'.
        control_key_set = getattr(self, "control_keys", None)
        if control_key_set is None:
            def _is_control(key):
                return key.startswith("control_")
        else:
            def _is_control(key):
                return key in control_key_set

        for arg in args:
            key, val = _parse_arg(arg)
            if key is None:
                continue
            if _is_control(key):
                control_args[key] = val
            else:
                # Custom arguments are treated as nested but may be
                # distinguished by a 'custom_' prefix. They are simply
                # added to nested_args.
                nested_args[key] = val

        return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not extra_vars:
            return vars_dict
        for var in extra_vars:
            if '=' not in var:
                continue
            key, val = var.split('=', 1)
            # If the value contains commas, treat it as a list
            if ',' in val:
                val = val.split(',')
            vars_dict[key] = val
        return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    from pathlib import Path
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    plugin_dir = Path(plugin_dir)
    spec_file = None
    for ext in ("yaml", "yml", "json"):
        candidate = plugin_dir / f"plugin.{ext}"
        if candidate.is_file():
            spec_file = candidate
            break
    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    if spec_file.suffix in {".yaml", ".yml"}:
        if yaml is None:
            raise ImportError("PyYAML is required to parse YAML plugin spec")
        with spec_file.open("r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    else:
        with spec_file.open("r", encoding="utf-8") as f:
            data = json.load(f)

    def _flatten(obj, parent_key=""):
        items = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                items.update(_flatten(v, new_key))
        elif isinstance(obj, list):
            for idx, v in enumerate(obj):
                new_key = f"{parent_key}.{idx}" if parent_key else str(idx)
                items.update(_flatten(v, new_key))
        else:
            items[parent_key] = obj
        return items

    return _flatten(data) if data is not None else {}
